def copy_botox_revisions(apps, schema_editor):
    ContentType       = apps.get_model("contenttypes", "ContentType")
    BotoxFormRevision = apps.get_model("forms_system", "BotoxFormRevision")
    FormRevision      = apps.get_model("forms_system", "FormRevision")

    botox_ct, _ = ContentType.objects.get_or_create(app_label="forms_system", model="botoxconsentform")
    for old in BotoxFormRevision.objects.order_by("created_at", "pk"):
        new = FormRevision.objects.create(
            content_type=botox_ct, object_id=old.form_id, user_id=old.user_id,
            section=old.section, action=old.action, data=old.data,
        )
        # created_at is auto_now_add, so restore the original timestamp after.
        FormRevision.objects.filter(pk=new.pk).update(created_at=old.created_at)


